/// Convert a D-Bus type signature to a human-readable description
pub fn dbus_signature_to_human(sig: &str) -> String {
    match sig {
670→        "s" => "String".to_string(),
        "b" => "Boolean".to_string(),
        "y" => "Byte".to_string(),
        "n" => "Int16".to_string(),
        "q" => "Uint16".to_string(),
        "i" => "Int32".to_string(),
        "u" => "Uint32".to_string(),
        "x" => "Int64".to_string(),
        "t" => "Uint64".to_string(),
        "d" => "Double".to_string(),
680→        "o" => "ObjectPath".to_string(),
        "g" => "Signature".to_string(),
        "v" => "Variant".to_string(),
        "h" => "UnixFd".to_string(),
        "" => "()".to_string(),
        _ if sig.starts_with("a{") && sig.ends_with('}') => {
            let inner = &sig[2..sig.len() - 1];
            if inner.len() >= 2 {
                format!(
                    "Dict<{}, {}>",
690→                    dbus_signature_to_human(&inner[..1]),
                    dbus_signature_to_human(&inner[1..])
